<?php include "../auth/cek_login.php";include "../koneksi.php";$id=$_GET['id'];$t=mysqli_fetch_assoc(mysqli_query($conn,"SELECT * FROM transaksi WHERE id=$id"));if(!$t)die('Transaksi tidak ditemukan');if(isset($_POST['proses'])){$tgl=$_POST['tanggal'];$denda=(int)$_POST['denda'];$cat=$_POST['catatan'];mysqli_query($conn,"INSERT INTO pengembalian(id_transaksi,tanggal_kembali,denda,catatan) VALUES($id,'$tgl',$denda,'$cat')");$ds=mysqli_query($conn,"SELECT * FROM detail_transaksi WHERE id_transaksi=$id");while($d=mysqli_fetch_assoc($ds))mysqli_query($conn,"UPDATE barang SET stok=stok+{$d['jumlah']} WHERE id={$d['id_barang']}");mysqli_query($conn,"UPDATE transaksi SET status='Dikembalikan',total_harga=total_harga+$denda WHERE id=$id");header("Location:index.php");exit;}?><!doctype html><html><head><title>Pengembalian</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="content"><h1>Pengembalian <?=$t['kode_transaksi']?></h1><form method="post"><input type="date" name="tanggal" value="<?=date('Y-m-d')?>" required><input type="number" name="denda" value="0" min="0" placeholder="Denda"><textarea name="catatan" placeholder="Catatan"></textarea><button name="proses">Selesaikan Transaksi</button></form></div></body></html>